// Config global del bot
const config = {
  // JID del grupo REMITOS
  groupJid: '120363039852043503@g.us',

  // ID del Google Sheet (de la URL: docs.google.com/spreadsheets/d/<ESTE_ID>/edit)
  spreadsheetId: '1dLd0fgqVrDLliq4sCdVxMtXdavWuREkEeZcODDk-t8Y',

  // Evolution API (instancia self-hosted en EasyPanel)
  evolutionApiUrl: 'https://evolutioapi-evolution-api.mknton.easypanel.host',
  evolutionInstance: 'winndia bot',

  // Mapa de alias de cliente -> nombre exacto de la hoja en el Sheet.
  // Agregá aliases para cada cliente con todas las formas en que puede aparecer en remitos/comprobantes.
  clientAliases: {
    'ramiro rendon': 'ROCAS RAMIRO',
    'ramiro rendón': 'ROCAS RAMIRO',
    'rodriguez rendon ramiro': 'ROCAS RAMIRO',
    'cinna': 'CINNA',
    'veggia': 'VEGGIA',
    'fatima kuns': 'FATIMA KUNS',
    'bucco': 'BUCCO',
    'indara estefi': 'INDARA ESTEFI',
    'bloomchic': 'BLOOMCHIC',
    'tosco': 'TOSCO',
    'you are by alexia': 'YOU ARE BY ALEXIA',
    'niusta': 'NIUSTA',
    'principito': 'PRINCIPITO',
    'margarita': 'MARGARITA',
    'zapin': 'zapin',
    'de pueblo': 'de pueblo',
    'daielo': 'daielo'
  }
};

return [{ json: { config, original: $input.first().json } }];

// Parseamos la respuesta de Claude y matcheamos cliente con la hoja
const claudeResp = $input.first().json;
const rawText = claudeResp.content?.[0]?.text || '{}';

let extracted;
try {
  // A veces Claude envuelve en ```json ... ```, lo limpiamos
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = { tipo: 'desconocido', faltante: 'No se pudo parsear: ' + rawText.slice(0, 100), confianza: 'baja' };
}

// Traemos la config desde el primer item de la ejecución
const configItem = $('Config').first().json;
const aliases = configItem.config.clientAliases;
const original = configItem.original;

// Match de cliente (lowercase, sin tildes, comparación simple)
function normalize(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, '').trim();
}

let sheetName = null;
const detected = normalize(extracted.cliente_detectado);
if (detected) {
  for (const [alias, sheet] of Object.entries(aliases)) {
    if (detected.includes(normalize(alias)) || normalize(alias).includes(detected)) {
      sheetName = sheet;
      break;
    }
  }
}

// Determinar cuenta (1 o 2) en base al tipo
const esCheque = extracted.tipo === 'pago_cheque';
const esCta1 = extracted.tipo === 'remito_cta1';
const esCta2 = extracted.tipo === 'remito_cta2';
const esPago = extracted.tipo === 'pago_transferencia' || extracted.tipo === 'pago_cheque';
const esNotaCredito = extracted.tipo === 'nota_credito';

// Para pagos, sin contexto adicional asumimos cta1 (ajustable). El usuario podrá corregir respondiendo.
let cuenta = null;
if (esCta1) cuenta = 1;
else if (esCta2) cuenta = 2;
else if (esPago || esNotaCredito) cuenta = 1; // default, se puede mejorar

const tieneTodoLoNecesario = sheetName && cuenta && extracted.monto && extracted.confianza !== 'baja';

return [{
  json: {
    extracted,
    sheetName,
    cuenta,
    esCheque,
    esPago,
    esCta1,
    esCta2,
    tieneTodoLoNecesario,
    config: configItem.config,
    senderJid: original.data.key.participant || original.data.key.remoteJid,
    messageId: original.data.key.id,
    groupJid: configItem.config.groupJid
  }
}];

// Calcula en qué columnas escribir según cta1 o cta2
const d = $input.first().json;
const e = d.extracted;

// cta 2 -> A:F (FECHA, COMPROBANTE, NOTA, DEBE, HABER, SALDO)
// cta 1 -> H:M (mismo orden, sin tocar SALDO)
const rangeStart = d.cuenta === 1 ? 'H' : 'A';
const rangeEnd = d.cuenta === 1 ? 'L' : 'E'; // hasta HABER, no escribimos SALDO

// DEBE vs HABER
let debe = '';
let haber = '';
if (d.esPago || e.tipo === 'pago_transferencia' || e.tipo === 'pago_cheque') {
  haber = e.monto;
} else if (e.tipo === 'nota_credito') {
  haber = e.monto; // las NC son a favor del cliente, descuentan deuda
} else {
  debe = e.monto;
}

const comprobante = e.numero_comprobante || 'pago';
const nota = e.nota || '';

return [{
  json: {
    ...d,
    sheetRange: `${d.sheetName}!${rangeStart}:${rangeEnd}`,
    rowValues: [e.fecha || '', comprobante, nota, debe, haber]
  }
}];

